 6442,6432,6433,11,68,6446,6028,6023,11,90,6448,6028,6446,16,90,6444,6448,6446,18,84,6449,6448,6444,18,84,6443,6449,6444,16,73,6450,6449,6443,16,72,6443,1887,6450,11,86,6450,1887,1886,11,83,6448,5885,6028,16,93,6373,5885,6448,18,92,6449,6373,6448,16,85,
 6374,6373,6449,16,84,6450,6374,6449,16,73,6375,6374,6450,16,73,6375,6450,1892,11,84,1892,6450,1886,11,85,6311,6313,6451,16,80,5839,6451,6313,16,93,5840,6451,5839,16,93,5840,6452,6451,16,94,5842,6452,5840,11,93,6311,6451,6453,16,79,6453,6451,6452,18,79,
 6453,6309,6311,16,67,6453,6304,6309,11,67,6306,6304,6453,18,65,6452,6306,6453,18,78,6308,6306,6452,18,77,5842,6308,6452,16,91,5845,6308,5842,11,91,6454,6394,6392,18,80,6454,6000,6394,16,93,5997,6000,6454,11,93,6455,5997,6454,16,94,5995,5997,6455,11,93,
 6455,6454,6456,16,79,6456,6454,6392,16,79,6456,6392,6390,16,67,6385,6456,6390,16,67,6387,6456,6385,16,65,6387,6455,6456,16,78,6389,6455,6387,16,77,6455,6389,5995,16,91,5995,6389,5996,11,91,
}
local sin,cos,sqrt,pi = math.sin,math.cos,math.sqrt,math.pi
-- Keeps the reef shoulders low around the open water column of the battle (as Kanto).
local function reefLimit(x,z,r,tx)
 r=r or 0
 if (x-tx)^2+(z+25)^2<(19+r)^2 then return -44 end
 local radial=sqrt(x*x+z*z)
 if z>18 and math.abs(x)<35 then return -42 end
 if radial>43 then return -31.5 end
 if radial>32 then return -34.5 end
 return -44
end

-- Explicit scenery key (not a map id): the host routes Johto surf battles to it.
function R.appliesTo(id) return id=='JOHTO_SEA' end
function R.button(h) end -- Preserve the host's NEUTRAL Pokeball button.
-- Sea-only setup hook, before arena placement/cache creation (same contract as Kanto Sea).
function R.configureSetup(setup)
 assert(setup and setup.actors,'Sea requires the actual host actor setup')
 for _,side in ipairs({'player','enemy'})do
  setup.actors[side][2]=setup.cameraMode=='behind' and -38 or R.battleY
  if setup.cameraMode~='behind' then setup.actors[side][3]=-36 end
 end
 setup.seaActorHeight=true
 return setup
end

local function innerY(x,z)
 return -1-66*sqrt(math.max(0,1-(x*x+z*z)/(73.5*73.5)))
end
local function key(x,z) return x..':'..z end
local function noise(x,z) return (sin(x*17.31+z*43.17)*437.58)%1 end
-- Colours of the Silver intro: pale green sand, blue rock, blue waving seaweed.
local sand={{.70,.85,.60},{.73,.87,.62},{.76,.89,.65},{.67,.83,.58},{.72,.86,.63}}
local rock={{.24,.40,.62},{.29,.46,.69},{.35,.53,.75},{.40,.58,.78},{.27,.42,.64}}
local weed={{.30,.50,.82},{.40,.60,.89},{.50,.70,.94},{.26,.44,.74}}
local pebble={{.52,.68,.86},{.60,.75,.90},{.46,.62,.80}}

-- The tiled terrain follows the INNER bowl, with the deep sandy pocket of the Shellder.
local POCKET={8,-8,18}
local function terrain()
 local cells={}
 for ix=-17,17 do for iz=-17,17 do
  local x,z=ix*4,iz*4
  local far=sqrt((math.abs(x)+2)^2+(math.abs(z)+2)^2)
  if far<65.2 then
   local mound=3*sin(x*.075)*sin(z*.085)+2*cos((x-z)*.075)
   local y=math.ceil(math.max(-60+mound,innerY(far,0)+2.4)/2)*2
   if (x-POCKET[1])^2+(z-POCKET[2])^2<POCKET[3]^2 then y=-60 end
   cells[key(ix,iz)]={x=x,z=z,y=y,ix=ix,iz=iz}
  end
 end end
 return cells
end

local function drawMesh(quad,V,F,PAL,ox,oy,oz,yaw,sc)
 local c,s=cos(yaw or 0),sin(yaw or 0);sc=sc or 1
 local function at(i)local k=(i-1)*3;local x,y,z=V[k+1]*sc,V[k+2]*sc,V[k+3]*sc
  return{ox+x*c+z*s,oy+y,oz-x*s+z*c}end
 for k=1,#F,5 do local a=at(F[k]);quad(a,at(F[k+1]),at(F[k+2]),a,PAL[F[k+3]],F[k+4]/100)end
end

function R.build(h,setup)
 assert(h and type(h.quad)=='function','JohtoSea.build requires host quad')
 assert(setup and setup.trainers and setup.actors,'JohtoSea requires unchanged host participant setup')
 assert(setup.seaActorHeight==true,'Call configureSetup before building/placing Sea actors')
 local behind=setup.cameraMode=='behind'
 local openX=behind and -17 or -8
 local function reefCeiling(x,z,r)return reefLimit(x,z,r,openX)end
 local Q=h.quad
 local function group(s) if h.group then h.group(s) end end
 local function quad(a,b,c,d,col,shade) Q(a,b,c,d,col,shade or 1) end
 local function box(x,y,z,w,ht,d,col)
  local a,b,e,f,t=x-w/2,x+w/2,z-d/2,z+d/2,y+ht
  quad({a,t,e},{b,t,e},{b,t,f},{a,t,f},col)
  quad({a,y,f},{b,y,f},{b,t,f},{a,t,f},col,.83)
  quad({b,y,e},{a,y,e},{a,t,e},{b,t,e},col,.68)
  quad({b,y,f},{b,y,e},{b,t,e},{b,t,f},col,.89)
  quad({a,y,e},{a,y,f},{a,t,f},{a,t,e},col,.74)
 end
 local cells=terrain()
 local function floorAt(x,z)
  local p=cells[key(math.floor(x/4+.5),math.floor(z/4+.5))]
  return p and p.y or innerY(x,z)+2.4
 end
 local function footY(x,z,r)
  local y=floorAt(x,z)
  for _,dx in ipairs({-r,0,r})do for _,dz in ipairs({-r,0,r})do
   y=math.max(y,floorAt(x+dx,z+dz))
  end end
  return y
 end
 local function column(x,z,w,d,top,col)
  -- A pillar is divided at terrain cell boundaries, rooting every visible foot.
  local x0,x1,z0,z1=x-w/2,x+w/2,z-d/2,z+d/2
  for ix=math.floor((x0+2)/4),math.floor((x1+2-1e-6)/4)do
   for iz=math.floor((z0+2)/4),math.floor((z1+2-1e-6)/4)do
    local a,b=math.max(x0,ix*4-2),math.min(x1,ix*4+2)
    local c,dz=math.max(z0,iz*4-2),math.min(z1,iz*4+2)
    local far=sqrt(math.max(math.abs(a),math.abs(b))^2+math.max(math.abs(c),math.abs(dz))^2)
    local y=math.max(floorAt(ix*4,iz*4),innerY(far,0)+.3)
    if top>y then box((a+b)/2,y,(c+dz)/2,b-a,top-y,dz-c,col)end
   end
  end
 end
 local function beveled(x,y,z,w,ht,d,col)
  local cut=math.min(w,d)*.17
  local p={{-w/2+cut,-d/2},{w/2-cut,-d/2},{w/2,-d/2+cut},{w/2,d/2-cut},
   {w/2-cut,d/2},{-w/2+cut,d/2},{-w/2,d/2-cut},{-w/2,-d/2+cut}}
  for i,a in ipairs(p)do local b=p[i%8+1]
   quad({x+a[1],y,z+a[2]},{x+b[1],y,z+b[2]},
    {x+b[1]*.92,y+ht,z+b[2]*.92},{x+a[1]*.92,y+ht,z+a[2]*.92},col,.77+.12*sin(i*.8))
   quad({x,y+ht,z},{x+a[1]*.92,y+ht,z+a[2]*.92},
    {x+b[1]*.92,y+ht,z+b[2]*.92},{x,y+ht,z},col)
  end
 end

 -- 1. Inner liner of the bowl: the deep blue band of the intro, lighter towards the top.
 group('inner_porcelain')
 for j=0,15 do
  local a,b=j*pi/32,(j+1)*pi/32
  local ra,rb=73.5*sin(a),73.5*sin(b)
  local ya,yb=-1-66*cos(a),-1-66*cos(b)
  local c={.15+j*.012,.30+j*.016,.50+j*.017}
  for i=0,95 do local u,v=i*pi/48,(i+1)*pi/48
   quad({ra*cos(u),ya,ra*sin(u)},{ra*cos(v),ya,ra*sin(v)},
    {rb*cos(v),yb,rb*sin(v)},{rb*cos(u),yb,rb*sin(u)},c,.87+.07*sin(u))
  end
 end
 for i=0,95 do local u,v=i*pi/48,(i+1)*pi/48
  quad({73.5*cos(u),-1,73.5*sin(u)},{73.5*cos(v),-1,73.5*sin(v)},
   {73.5*cos(v),0,73.5*sin(v)},{73.5*cos(u),0,73.5*sin(u)},{.62,.78,.86},.88)
 end

 -- 2. Seabed: pale green sand in the valley and the pocket, blue rock up the walls.
 group('seabed')
 for ix=-17,17 do for iz=-17,17 do
  local p=cells[key(ix,iz)]
  if p then
   local x,z,y=p.x,p.z,p.y
   local c=sand[1+math.floor(noise(ix,iz)*#sand)]
   if (math.abs(x)>27 or z<-41) and noise(ix+31,iz+17)>.3 then
    c=rock[2+math.floor(noise(ix+4,iz)*3)]
   end
   quad({x-2,y,z-2},{x+2,y,z-2},{x+2,y,z+2},{x-2,y,z+2},c)
   local sides={{-1,0,x-2,z+2,x-2,z-2},{1,0,x+2,z-2,x+2,z+2},
    {0,-1,x-2,z-2,x+2,z-2},{0,1,x+2,z+2,x-2,z+2}}
   for _,s in ipairs(sides)do
    local n=cells[key(ix+s[1],iz+s[2])]
    local low=n and n.y or math.max(innerY(s[3],s[4]),innerY(s[5],s[6]))+.2
    if low<y then quad({s[3],low,s[4]},{s[5],low,s[6]},
     {s[5],y,s[6]},{s[3],y,s[4]},c,.77)end
   end
  end
 end end

 -- 3. The two battle shelves under the actors (Kanto Sea contract): tops at actor height.
 local battleForms={}
 group('battle_reef')
 for n,side in ipairs({'player','enemy'})do
  local p=setup.actors[side];local dx,dz
  if behind then dx,dz=(side=='player' and -2 or 3),(side=='player' and 2 or -13)
  else dx,dz=(side=='player' and -3 or 3),0 end
  local rx,rz=p[1]+dx,p[3]+dz
  local base=math.max(-56,footY(rx,rz,10.5)+.7)
  column(rx,rz,20,19,base,rock[2])
  local tiers={}
  for k=0,3 do
   local f=1-k/3
   local x,z=p[1]+dx*f,p[3]+dz*f
   local low=base+(p[2]-.7-base)*k/4
   local high=base+(p[2]-.7-base)*(k+1)/4
   local w,d=13.8+6.2*f,12.5+6.5*f
   beveled(x,low,z,w,high-low,d,rock[(k+n)%5+1])
   tiers[#tiers+1]={x,z,w,d,low,high}
  end
  -- Sand cap, flat at the exact standing height.
  for ix=-4,4 do for iz=-3,3 do
   local x,z=ix*1.6,iz*1.6
   if (x/7.3)^2+(z/6.1)^2<1 then
    box(p[1]+x,p[2]-.7,p[3]+z,1.6,.7,1.6,sand[2+(ix+iz+20)%3])
   end
  end end
  battleForms[#battleForms+1]={tiers=tiers}
 end
 local function clearOfBattle(x,z,r,low,high)
  for _,form in ipairs(battleForms)do for _,q in ipairs(form.tiers)do
   if high>q[5] and low<q[6] and math.abs(x-q[1])<q[3]*.5+r+.4
    and math.abs(z-q[2])<q[4]*.5+r+.4 then return false end
  end end
  return true
 end

 -- 4. Blue rock walls in an asymmetric horseshoe, like the outcrop at the right of the intro.
 local reefs={}
 local wallSites={{-42,-25,11,11},{-34,-38,10,10},{-46,-8,10,12},{-40,14,11,10},
  {-28,32,10,9},{40,-24,11,11},{33,-40,10,9},{46,-4,10,12},{42,16,11,10},{29,34,10,9},
  {-10,-50,10,8},{14,-50,10,8}}
 group('reef_rock')
 for n,p in ipairs(wallSites)do
  local x,z,w,d=p[1],p[2],p[3],p[4]
  for _,side in ipairs({'player','enemy'})do local tr=setup.trainers[side]
   if math.abs(x-tr[1])<w*.6+7 and math.abs(z-tr[3])<d*.6+7 then
    x=tr[1]+(x<tr[1] and -1 or 1)*(w*.6+8)
   end
  end
  local y=footY(x,z,math.max(w,d)*.5)
  local top=math.max(y+.6,math.min(y+1.2+n%2,reefCeiling(x,z,5)-10))
  if clearOfBattle(x,z,math.max(w,d)*.5,y,top+1) then
   column(x,z,w,d,top-1.2,rock[n%5+1])
   beveled(x,top-1.2,z,w,1.2,d,rock[(n+1)%5+1])
   local bx,bz=x-w*.19,z-d*.16
   beveled(bx,top,bz,w*.55,1.0,d*.57,rock[(n+2)%5+1])
   reefs[#reefs+1]={x,z,w,d,top+1}
  end
 end
 -- The big rounded outcrop of the intro's Shellder frame, against the right-hand wall.
 group('reef_outcrop')
 local ox,oz=51,-20
 if behind then ox,oz=50,8 end
 do
  local y0=footY(ox,oz,6)
  for k=0,5 do
   local w=12-k*1.4;local d=11-k*1.2
   local top=math.min(y0+(k+1)*3.4,-26)
   local low=y0+k*3.4
   if top>low then
    if k==0 then column(ox-k*.6,oz,w,d,top,rock[(k%5)+1])
    else beveled(ox-k*.6,low,oz+k*.3,w,top-low,d,rock[(k%5)+1])end
   end
  end
  reefs[#reefs+1]={ox,oz,12,11,math.min(y0+20.4,-26)}
 end
 -- A real recess under an open lintel; its piers connect to the seabed (as Kanto).
 group('reef_cavity')
 column(23,2,3.2,4,-51,rock[2]);column(32,2,3.2,4,-51,rock[2])
 box(27.5,-51,2,12.2,2.4,4,rock[4])
 box(27.5,-48.6,2,8,.8,3.5,rock[3])

 local occupied={{27.5,2,7}}
 local function baseAt(x,z,r)
  local y=footY(x,z,r)
  for _,q in ipairs(reefs)do
   if math.abs(x-q[1])<q[3]*.5+r and math.abs(z-q[2])<q[4]*.5+r then
    y=math.max(y,q[5])
   end
  end
  return y
 end
 local function site(wantX,wantZ,r,headroom,pocketOK)
  for attempt=0,2500 do
   local a=attempt*2.399963;local shift=attempt==0 and 0 or .85*sqrt(attempt)
   local x,z=wantX+cos(a)*shift,wantZ+sin(a)*shift
   local good=x*x+z*z<(57-r)^2
   if not pocketOK and (x-POCKET[1])^2+(z-POCKET[2])^2<(POCKET[3]-1+r)^2 then good=false end
   if z>5 and z<43 and math.abs(x-(7-.28*z))<3+r then good=false end
   for _,side in ipairs({'player','enemy'})do local tr=setup.trainers[side]
    if math.abs(x-tr[1])<r+7.5 and math.abs(z-tr[3])<r+7.5 then good=false end
   end
   for _,q in ipairs(occupied)do
    if (x-q[1])^2+(z-q[2])^2<(r+q[3]+.35)^2 then good=false end
   end
   if good then
    local y=baseAt(x,z,r);local cap=reefCeiling(x,z,r)
    if cap-y>=headroom and clearOfBattle(x,z,r,y,cap) then
     occupied[#occupied+1]={x,z,r}
     return x,z,y,cap
    end
   end
  end
  return nil
 end
 local function plinth(x,z,y,r,n)
  column(x,z,r*1.7,r*1.65,y+.55,rock[n%5+1])
  beveled(x,y+.55,z,r*1.72,.55,r*1.67,rock[(n+1)%5+1])
  return y+1.1
 end

 -- 5. The Shellder: three of them in the deep sandy pocket, as the intro opens.
 local shellders={{2,-13,.2},{15,-10,-.3},{4,3,.05}}
 local pocketFloor=-60
 for i,s in ipairs(shellders)do
  group('pokemon_shellder_'..i)
  occupied[#occupied+1]={s[1],s[2],8.2}
  drawMesh(quad,shellderVerts,shellderFaces,shellderPalette,s[1],pocketFloor+.02,s[2],s[3],.9)
 end

 -- 6. Blue seaweed: tall waving ribbons with leaves on alternating sides (intro sprite).
 local function seaweed(x,z,y,ht,n,thick)
  thick=thick or .8
  local last=x
  for k=0,ht-1 do
   local sx=x+sin(k*.55+n*1.7)*1.1
   local c=weed[(n+k)%4+1]
   box(sx,y+k,z,thick,1,thick,c)
   if k%2==1 and k<ht-1 then
    local side=((k+n)%4<2) and 1 or -1
    box(sx+side*(thick*.5+.45),y+k+.3,z,.9,.45,thick*.75,weed[(n+k+1)%4+1])
   end
   last=sx
  end
  box(last,y+ht,z,thick*.7,.6,thick*.7,weed[3])
 end
 group('seaweed_pocket')
 -- Clumps ring the Shellder pocket; each rests on the pocket floor or its terraces.
 for n=0,15 do
  local a=n*2*pi/16+.3
  local rr=12.5+(n%3)*2.2
  local x,z=POCKET[1]+cos(a)*rr,POCKET[2]+sin(a)*rr
  local good=true
  for _,s in ipairs(shellders)do if (x-s[1])^2+(z-s[2])^2<10^2 then good=false end end
  if good then
   local y=footY(x,z,1.2)
   local ht=math.min(11+(n*5)%6,math.floor(-44-y))
   if ht>=3 and clearOfBattle(x,z,1.6,y,y+ht+1) then
    for j=-1,1 do
     if j==0 or n%2==0 then
      local jx,jz=x+j*1.4,z+((j+n)%2)*.7
      seaweed(jx,jz,footY(jx,jz,.6),math.max(3,ht-math.abs(j)*3),n+j,.8)
     end
    end
    occupied[#occupied+1]={x,z,2.4}
   end
  end
 end
 group('seaweed')
 local gardens={{-48,-23},{-44,-34},{-31,-47},{-14,-49},{24,-48},{38,-36},{47,-12},
  {-46,4},{-38,24},{-20,40},{20,40},{40,24},{-24,-14},{30,-8},{-30,12},{22,18},{-12,24}}
 for n,p in ipairs(gardens)do
  local x,z,y,cap=site(p[1],p[2],2.3,6.0)
  if x then
   y=plinth(x,z,y,2.0,n)
   for j=-1,1 do
    local ht=math.min(6+(n+j*3)%7,math.floor(cap-y-.6))
    if ht>=3 then seaweed(x+j*1.35,z+((j+n)%2)*.6,y,ht,n+j,.75)end
   end
  end
 end

 -- 7. Small round blue stones and pebbles on the sand (intro seabed).
 group('seabed_details')
 for n,p in ipairs({{-17,20},{19,14},{-32,14},{34,-30},{-28,-12},{-16,-37},{22,-23},
  {-37,-3},{27,18},{-24,37},{-8,39},{-6,6},{18,4}})do
  local x,z,y=site(p[1],p[2],1.6,1.8)
  if x then
   beveled(x,y,z,2.6,.9,2.2,pebble[n%3+1])
   beveled(x+.2,y+.9,z-.1,1.6,.55,1.4,pebble[(n+1)%3+1])
  end
 end
 for i=1,160 do
  local x,z=(noise(i,12)-.5)*110,(noise(6,i)-.5)*110
  local good=x*x+z*z<55^2
  for _,q in ipairs(occupied)do if (x-q[1])^2+(z-q[2])^2<(q[3]+1.1)^2 then good=false end end
  if good then
   local w=.7+noise(i,22)*1.1;local y=baseAt(x,z,w*.5)
   if clearOfBattle(x,z,w,y,y+.45)then column(x,z,w,w*.8,y+.45,pebble[i%3+1])end
  end
 end

 -- 8. Bubbles rising from the Shellder: thin rings facing the camera.
 group('bubbles')
 local eye={0,157,205}
 local function bubble(x,y,z,r)
  local dx,dy,dz=eye[1]-x,eye[2]-y,eye[3]-z;local l=sqrt(dx*dx+dy*dy+dz*dz)
  dx,dy,dz=dx/l,dy/l,dz/l
  local ux,uy,uz=dz,0,-dx;local ul=sqrt(ux*ux+uz*uz);ux,uz=ux/ul,uz/ul
  local vx,vy,vz=dy*uz-dz*uy,dz*ux-dx*uz,dx*uy-dy*ux
  local function P(a,rr)return{x+(ux*cos(a)+vx*sin(a))*rr,y+(uy*cos(a)+vy*sin(a))*rr,z+(uz*cos(a)+vz*sin(a))*rr}end
  for i=0,11 do local a,b=i*pi/6,(i+1)*pi/6
   quad(P(a,r),P(b,r),P(b,r*.72),P(a,r*.72),{.92,.97,1},1)
  end
 end
 for k,b in ipairs({{2,-49.5,-13,1.1},{3.4,-46,-14,.8},{1.4,-42.5,-12.5,1.2},
  {17,-49,-10,.9},{16,-45.5,-11,1.1},{6,-49,4,.8},{7.4,-45,3,1.0}})do
  bubble(b[1],b[2],b[3],b[4])
 end

 -- 9. Mid-water: the Magikarp school of the intro, all swimming the same way.
  local school=behind and {{-42,-15,2,1.65},{40,-18,-22,1.5},{34,-16,6,1.7},{40,-20,30,1.55}}
  or {{-40,-16,30,1.65},{-20,-18,44,1.5},{40,-15,10,1.7},{-46,-16,-14,1.55}}
 for i,m in ipairs(school)do
  group('pokemon_magikarp_'..i)
  drawMesh(quad,magikarpVerts,magikarpFaces,magikarpPalette,m[1],m[2],m[3],m[4],1.12)
 end

 -- 10. Trainer supports: rock columns from the seabed under the host pads (as Kanto).
 group('trainer_supports')
 for _,side in ipairs({'player','enemy'})do
  local p=setup.trainers[side];local x,z=p[1],p[3]
  column(x,z,13,12,-20,rock[2]);column(x-.4,z,11,10.5,-10,rock[3])
  column(x,z,9.5,9.5,-4,rock[2]);box(x,-4,z,12.5,4,12.5,rock[3])
  if behind then
   local d=z>0 and -1 or 1;column(x,z+d*8,8,3,0,rock[3])
  else
   local d=x>0 and -1 or 1;column(x+d*8,z,3,8,0,rock[3])
  end
 end

 -- 11. Level 0: Lapras crossing the surface towards the left, flippers under the water.
 group('pokemon_lapras')
 if behind then
  drawMesh(quad,laprasVerts,laprasFaces,laprasPalette,-14,-7.6,-50,-.6,.85)
 else
  drawMesh(quad,laprasVerts,laprasFaces,laprasPalette,0,-7.6,-54,-.6,.85)
 end
end
-- One horizontal water surface. Sixth argument is ALPHA, never opaque shade.
function R.buildWater(h)
 assert(h and type(h.quad)=='function','buildWater requires an RGBA quad collector')
 for i=0,95 do local a,b=i*pi/48,(i+1)*pi/48
  h.quad({0,R.waterY,0},{73.5*cos(a),R.waterY,73.5*sin(a)},
   {73.5*cos(b),R.waterY,73.5*sin(b)},{0,R.waterY,0},{.10,.47,.74},.25)
 end
end
-- Allocate once per arena cache entry. Draw in the SAME depth-backed 3D canvas,
-- after opaque scenery/participants and before above-water translucent FX + HUD.
-- Alpha depth-test keeps the original shell and everything above water opaque.
function R.newWaterRenderer(api)
 assert(api and api.Voxel3D and api.Mat4,'Water renderer requires Voxel3D and Mat4')
 local g=love.graphics;local mesh,shader;local S={}
 local function init()
  local v={}
  R.buildWater({quad=function(a,b,c,d,rgb,alpha)
   -- Each fan quad is one nondegenerate triangle, not two coincident surfaces.
   for _,p in ipairs({a,b,c})do v[#v+1]={p[1],p[2],p[3],rgb[1],rgb[2],rgb[3],alpha}end
  end})
  local ok,err=pcall(function()
   mesh=g.newMesh({{'VertexPosition','float',3},{'VertexColor','float',4}},v,'triangles','static')
   shader=g.newShader([[
    uniform float seaTime;
    varying vec2 seaXZ;
    vec4 effect(vec4 color, Image tex, vec2 uv, vec2 screen) {
     vec2 p=seaXZ;
     float w=sin(p.x*.20+p.y*.31+seaTime*.55)*sin(p.y*.36-p.x*.08-seaTime*.38);
     float ripple=smoothstep(.48,.90,w);
     float rim=smoothstep(69.5,73.4,length(p));
     float edge=.5+.5*sin(p.y*.55+p.x*.34+seaTime*.4);
     float crest=smoothstep(.982,.998,sin(p.y*.23+p.x*.075+sin(p.x*.14)*.8+seaTime*.42));
     float broken=smoothstep(-.1,.5,sin(p.x*.31-seaTime*.2));
     float glint=crest*broken;
     float light=ripple*.28+rim*edge*.19+glint*.40;
     vec3 tint=mix(color.rgb,vec3(.61,.86,.89),light);
     float alpha=color.a + ripple*.085 + rim*edge*.09+glint*.12;
     return vec4(tint,alpha);
    }]],[[
    uniform mat4 vp;
    uniform mat4 model;
    varying vec2 seaXZ;
    vec4 position(mat4 transform_projection,vec4 p) {
     seaXZ=p.xz;
     return vp*model*p;
    }]])
  end)
  if not ok then
   if mesh then mesh:release()end;if shader then shader:release()end
   mesh,shader=nil,nil;error(err)
  end
 end
 function S.draw(arena,y,time)
  assert(arena and arena.mid,'Sea water needs arena.mid')
  if not mesh then init()end
  g.push('all')
  local ok,err=pcall(function()
   g.setShader(shader)
   shader:send('vp','row',api.Voxel3D.vp)
   shader:send('model','row',api.Mat4.translate(arena.mid[1],y,arena.mid[2]))
   shader:send('seaTime',time or 0)
   g.setColor(1,1,1,1);g.setBlendMode('alpha','alphamultiply')
   g.setMeshCullMode('none');g.setDepthMode('lequal',false)
   g.draw(mesh)
  end)
  g.pop();if not ok then error(err)end
 end
 function S.release()
  if mesh then mesh:release()end;if shader then shader:release()end
  mesh,shader=nil,nil
 end
 return S
end
return R
